function renderSearch(){setTitle('Search book','Lehrbuch + Arbeitsbuch OCR');$('#pageHost').innerHTML=`<section class="panel" style="margin-top:0"><h2>Search source text</h2><input class="answer-input" id="bookSearch" autocomplete="off" placeholder="Search German word or phrase…"><div class="source-select" style="margin-top:10px"><select id="searchSource"><option value="all">Both books</option><option value="lb">Lehrbuch</option><option value="ab">Arbeitsbuch</option></select><select id="searchChapter"><option value="all">All chapters</option>${D.chapters.map(c=>`<option value="${c.id}">Kapitel ${c.id}</option>`).join('')}</select></div><div id="searchResults" class="search-results"></div></section>`;const go=()=>{let q=norm($('#bookSearch').value.trim()),src=$('#searchSource').value,cid=$('#searchChapter').value;if(q.length<2){$('#searchResults').innerHTML='<p class="muted">Type at least two characters.</p>';return}let hits=D.searchPages.filter(x=>(src==='all'||x.source===src)&&norm(x.text).includes(q));if(cid!=='all'){const c=chapter(+cid);hits=hits.filter(x=>x.source==='lb'?(x.page>=c.lbStart&&x.page<=c.lbEnd):(x.page>=c.abStart&&x.page<=c.abEnd))}hits=hits.slice(0,70);$('#searchResults').innerHTML=hits.map(x=>{let text=x.text,idx=norm(text).indexOf(q),a=Math.max(0,idx-90),b=Math.min(text.length,idx+180);return `<div class="search-result search-hit" data-hit="${x.source}:${x.page}"><b>${x.source==='lb'?'Lehrbuch':'Arbeitsbuch'} · page ${printedPage(x.page)}</b><div class="skill-chips">${pageSkill(x.source,x.page).map(k=>`<span>${k}</span>`).join('')}</div><div class="muted">…${esc(text.slice(a,b))}…</div></div>`}).join('')||'<p class="muted">No matches.</p>';$$('[data-hit]').forEach(h=>h.onclick=()=>{const [s,p]=h.dataset.hit.split(':');showViewer(s,+p)})};$('#bookSearch').oninput=go;$('#searchSource').onchange=go;$('#searchChapter').onchange=go}
