function testAnswerCorrect(v,mode,answer){if(mode==='article')return norm(answer)===norm(nounArticle(v));if(mode==='missing'||mode==='context')return strictSpellingNorm(answer)===strictSpellingNorm(testSession.answer);const variants=[fullRecallDisplay(v),v.base,v.bare].filter(Boolean);return variants.some(x=>flexibleRecallNorm(answer)===flexibleRecallNorm(x))}
