function scheduleWordAdvance(ms){clearWordAdvanceTimer();const countdown=$('#wordAnswerCountdown'),started=Date.now(),update=()=>{if(countdown)countdown.textContent=`Next item automatically in ${Math.max(0,Math.ceil((ms-(Date.now()-started))/1000))}s`};update();wordCountdownTimer=setInterval(update,250);wordAdvanceTimer=setTimeout(advanceWordTest,ms)}
function submitTest(skip){if(!testSession||testSession.answered)return;const v=testSession.v,mode=testSession.modeNow,answer=skip?'':wordTestTypedAnswer(v,mode);if(!skip&&!wordTestAnswerReady(mode)){if(mode==='missing')$$('.missing-letter-input').find(input=>!String(input.value||'').trim())?.focus();return}const ok=!skip&&testAnswerCorrect(v,mode,answer);testSession.answered=true;testSession.attempts++;if(ok)testSession.score++;recordWordEvidence(v,mode,ok);contribution('Word Test');const expected=testSession.answer,fb=$('#testFeedback');fb.className=`feedback ${ok?'good':'bad'}`;fb.innerHTML=ok?`<div class="answer-study-card"><b>Correct ✓</b><span>${esc(answer)}</span></div>`:`<div class="answer-study-card"><b>${skip?'Study this item':'Not quite ✕'}</b><span>Answer:</span><b>${esc(expected)}</b><small>${esc(conciseTestMeaning(v))}</small></div>`;disableWordTestInputs();$('#checkTest').disabled=true;$('#dontKnow').disabled=true;fb.insertAdjacentHTML('beforeend','<div class="button-row" style="justify-content:center;margin-top:12px"><button class="secondary" id="hearWordAnswer">🔊 Listen</button><button class="primary" id="nextWordNow">Next</button><span class="muted" id="wordAnswerCountdown"></span></div>');$('#hearWordAnswer').onclick=()=>speakGerman(expected);$('#nextWordNow').onclick=advanceWordTest;const normalInput=$('#testInput');if(normalInput)normalInput.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();advanceWordTest()}};$$('.missing-letter-input').forEach(input=>input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();advanceWordTest()}});scheduleWordAdvance(skip?9000:ok?1800:5000)}
