$$('.nav-item').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#searchQuick').onclick=()=>navigate('search');$('#themeBtn').onclick=()=>setTheme(settings.theme==='dark'?'light':'dark');$('#menuBtn').onclick=()=>{if(window.matchMedia('(max-width:820px)').matches){document.body.classList.toggle('nav-open');$('#sidebar')?.classList.toggle('open');$('#backdrop')?.classList.toggle('active')}else{settings.sidebarCollapsed=!settings.sidebarCollapsed;localStorage.setItem(SETTINGS,JSON.stringify(settings));applySidebar()}};$('#backdrop').onclick=()=>{document.body.classList.remove('nav-open');$('#sidebar')?.classList.remove('open');$('#backdrop')?.classList.remove('active')};$('#viewerClose').onclick=closeViewer;$('#viewer').onclick=e=>{if(e.target.id==='viewer')closeViewer()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeViewer()});
applySidebar();refreshStreak();initGermanKeyboard();updateFinalExamNavIcon();if(state.last?.page==='chapters')openChapter(state.last.chapter||1,state.last.tab||'lehrbuch',state.last.activity||null);else navigate(state.last.page||'home');cloudBootstrapping=false;if(cloudReady()){lastCloudCheck=Date.now();cloudSyncNow({silent:true})}document.addEventListener('visibilitychange',()=>{if(!document.hidden&&cloudReady()&&Date.now()-lastCloudCheck>30000){lastCloudCheck=Date.now();cloudSyncNow({silent:true})}});window.addEventListener('online',()=>{if(cloudReady())cloudSyncNow({silent:true})});
